{
  "title": "古村落迷雾",
  "scene": "天色渐晚，李明和小伙伴们在古村落中探索。一阵风吹过，古树下的石碑上似乎出现了一些模糊的符号，孩子们讨论着那些字体的意义，但没有人能认出。不远处的古井旁，有一块破旧的木牌子，上面刻着一行字：‘黑夜中的光明’。",
  "goal": "找到通往村落深处的秘密入口。",
  "clue": "古树下的石碑和古井旁的木牌子。",
  "choices": [
    {"id": "A", "text": "询问周围的老人", "outcome": "村里的老人只是摇头，并未提供有用的线索。", "result": "fail", "next": "retry"},
    {"id": "B", "text": "尝试解读石碑上的符号", "outcome": "经过仔细观察，李明发现石碑上的符号和木牌子上的字有相似之处，猜测两者可能有关联。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "查看木牌子的背面", "outcome": "木牌子的背面其实还藏着一个暗格，里面有一张纸条，上面写着：‘黑夜中寻找光明之烛’。", "result": "success", "next": "next_level"}
  ]
}
